class Solution:
    def addNegabinary(self, arr1: List[int], arr2: List[int]) -> List[int]:
        def to_int(a):
            v = 0
            for d in a:
                v = v * (-2) + d
            return v
        n = to_int(arr1) + to_int(arr2)
        if n == 0:
            return [0]
        res = []
        while n != 0:
            res.append(n & 1)
            n = -(n >> 1)
        return res[::-1]

