class Solution {
public:
    vector<int> addNegabinary(vector<int>& arr1, vector<int>& arr2) {
        int i = arr1.size() - 1, j = arr2.size() - 1, carry = 0;
        vector<int> res;
        while (i >= 0 || j >= 0 || carry) {
            int s = carry;
            if (i >= 0) s += arr1[i--];
            if (j >= 0) s += arr2[j--];
            res.push_back(s & 1);
            carry = -(s >> 1);
        }
        while (res.size() > 1 && res.back() == 0) res.pop_back();
        reverse(res.begin(), res.end());
        return res;
    }
};

